function networkDelayTime(times, n, k) {
  const dist = new Array(n + 1).fill(Infinity);
  dist[k] = 0;
  for (let round = 1; round < n; round++) {   // a shortest path uses at most n - 1 edges
    let changed = false;
    for (const [u, v, w] of times) {
      if (dist[u] + w < dist[v]) {        // relax: a cheaper way to reach v through u
        dist[v] = dist[u] + w;
        changed = true;
      }
    }
    if (!changed) break;                  // nothing improved: every distance is final
  }
  const slowest = Math.max(...dist.slice(1));
  return slowest === Infinity ? -1 : slowest;
}

int networkDelayTime(int[][] times, int n, int k) {
    final int INF = Integer.MAX_VALUE;
    int[] dist = new int[n + 1];
    Arrays.fill(dist, INF);
    dist[k] = 0;
    for (int round = 1; round < n; round++) {        // a shortest path uses at most n - 1 edges
        boolean changed = false;
        for (int[] t : times) {
            int u = t[0], v = t[1], w = t[2];
            if (dist[u] != INF && dist[u] + w < dist[v]) {   // relax: a cheaper way to reach v through u
                dist[v] = dist[u] + w;
                changed = true;
            }
        }
        if (!changed) break;                         // nothing improved: every distance is final
    }
    int slowest = 0;
    for (int i = 1; i <= n; i++) slowest = Math.max(slowest, dist[i]);
    return slowest == INF ? -1 : slowest;
}

