function networkDelayTime(times, n, k) {
  const adj = Array.from({ length: n + 1 }, () => []);
  for (const [u, v, w] of times) adj[u].push([v, w]);
  const dist = new Array(n + 1).fill(Infinity);
  dist[k] = 0;
  const heap = new Heap((a, b) => a[0] - b[0]);   // [distance, node], closest first
  heap.push([0, k]);
  while (heap.size() > 0) {
    const [d, u] = heap.pop();
    if (d > dist[u]) continue;              // a stale entry: u was already reached cheaper
    for (const [v, w] of adj[u]) {
      if (d + w < dist[v]) {                // a cheaper way to reach v, through u
        dist[v] = d + w;
        heap.push([dist[v], v]);
      }
    }
  }
  const slowest = Math.max(...dist.slice(1));
  return slowest === Infinity ? -1 : slowest;
}

int networkDelayTime(int[][] times, int n, int k) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] t : times) adj.get(t[0]).add(new int[]{t[1], t[2]});
    int[] dist = new int[n + 1];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[k] = 0;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));   // [distance, node]
    heap.add(new int[]{0, k});
    while (!heap.isEmpty()) {
        int[] top = heap.poll();
        int d = top[0], u = top[1];
        if (d > dist[u]) continue;                   // a stale entry: u was already reached cheaper
        for (int[] e : adj.get(u)) {
            int v = e[0], w = e[1];
            if (d + w < dist[v]) {                   // a cheaper way to reach v, through u
                dist[v] = d + w;
                heap.add(new int[]{dist[v], v});
            }
        }
    }
    int slowest = 0;
    for (int i = 1; i <= n; i++) slowest = Math.max(slowest, dist[i]);
    return slowest == Integer.MAX_VALUE ? -1 : slowest;
}

int networkDelayTime(vector<vector<int>>& times, int n, int k) {
    vector<vector<pair<int, int>>> adj(n + 1);
    for (auto& t : times) adj[t[0]].push_back({t[1], t[2]});
    vector<int> dist(n + 1, INT_MAX);
    dist[k] = 0;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap;   // (distance, node), smallest first
    heap.push({0, k});
    while (!heap.empty()) {
        auto [d, u] = heap.top(); heap.pop();
        if (d > dist[u]) continue;                   // a stale entry: u was already reached cheaper
        for (auto [v, w] : adj[u]) {
            if (d + w < dist[v]) {                   // a cheaper way to reach v, through u
                dist[v] = d + w;
                heap.push({dist[v], v});
            }
        }
    }
    int slowest = *max_element(dist.begin() + 1, dist.end());
    return slowest == INT_MAX ? -1 : slowest;
}
